base=cfg['base_url'].rstrip('/'); token=cfg['token']
H={'Authorization': f'Bearer {token}', 'Content-Type':'application/json'}

def get(code):
    req=urllib.request.Request(f'{base}/api/v1/dev-sessions/{code}/full', headers=H)
    with urllib.request.urlopen(req, timeout=60) as r:
        return json.load(r)

# healthy sample
